package com.zenix.musicplayer;

import org.json.*;
import java.nio.charset.StandardCharsets;
import java.text.Normalizer;
import java.util.*;

/** Portable metadata contract shared with backupFormat.cjs. */
final class BackupFormat {
    static final int MAX_BYTES=48*1024*1024;
    static final List<String> SECTIONS=List.of("liked","favorites","playlists","history","profile","appearance","stats","personalFeatures","featureSettings");
    static String text(Object value,int limit)throws Exception{if(!(value instanceof String)||((String)value).length()>limit)throw new Exception("备份文件结构无效");return (String)value;}
    static String key(JSONObject track){return norm(track.optString("title"))+"\u0000"+norm(track.optString("artist"))+"\u0000"+norm(track.optString("album"))+"\u0000"+Math.round(track.optDouble("duration"));}
    static String norm(String text){return Normalizer.normalize(text,Normalizer.Form.NFKC).toLowerCase(Locale.ROOT);}
    static JSONObject track(JSONObject value)throws Exception{if(value==null)throw new Exception("备份歌曲格式无效");String source=value.optString("source");if(!source.equals("custom")&&!source.equals("online"))source="local";double duration=value.optDouble("duration",0);if(!Double.isFinite(duration)||duration<0||duration>86400)throw new Exception("歌曲时长无效");JSONObject result=Json.obj("id",text(value.opt("id"),24000),"title",text(value.opt("title"),300),"artist",text(value.optString("artist"),300),"album",text(value.optString("album"),300),"duration",duration,"source",source,"path","","audioUrl","");if(source.equals("local"))Json.put(result,"id","backup-local:"+java.net.URLEncoder.encode(key(result),StandardCharsets.UTF_8).replace("+","%20").replace("%21","!").replace("%27","'").replace("%28","(").replace("%29",")").replace("%7E","~"));else{if(value.has("providerId"))Json.put(result,"providerId",text(value.opt("providerId"),120));if(value.has("remoteId"))Json.put(result,"remoteId",text(value.opt("remoteId"),20000));}return result;}
    static JSONArray tracks(JSONArray values)throws Exception{if(values==null||values.length()>10000)throw new Exception("备份歌曲数量无效");JSONArray result=new JSONArray();for(int i=0;i<values.length();i++)result.put(track(values.getJSONObject(i)));return result;}
    static String image(Object value)throws Exception{String text=text(value,2*1024*1024);if(!text.isEmpty()&&!text.matches("data:image/(?:png|jpeg|webp|gif);base64,[A-Za-z0-9+/]+={0,2}"))throw new Exception("个人资料图片无效或超过 2 MiB");return text;}
    static JSONObject profile(JSONObject value)throws Exception{if(value==null)throw new Exception("个人资料格式无效");JSONObject result=new JSONObject();for(String key:List.of("name","bio","tagline","about","contact","tags","cardNumber","cardLine","lyricColor","lyricSize","email","subject","background","orbitCovers"))if(value.has(key)){if(key.equals("subject")||key.equals("background"))Json.put(result,key,image(value.opt(key)));else if(key.equals("orbitCovers")){JSONObject covers=value.getJSONObject(key),clean=new JSONObject();for(String kind:List.of("liked","favorites","history","playlists","library"))if(covers.has(kind))Json.put(clean,kind,image(covers.opt(kind)));Json.put(result,key,clean);}else if(key.equals("lyricSize")){double number=value.getDouble(key);if(!Double.isFinite(number)||number<14||number>48)throw new Exception("歌词字号无效");Json.put(result,key,number);}else Json.put(result,key,text(value.opt(key),key.equals("about")?2000:300));}return result;}
    static JSONObject stats(JSONObject value)throws Exception{if(value==null||value.optJSONObject("days")==null||value.optJSONObject("tracks")==null||!Double.isFinite(value.optDouble("startedAt",Double.NaN)))throw new Exception("听歌统计格式无效");JSONObject tracks=value.getJSONObject("tracks"),days=value.getJSONObject("days"),cleanTracks=new JSONObject(),cleanDays=new JSONObject();if(tracks.length()>5000||days.length()>366)throw new Exception("听歌统计数量过大");for(Iterator<String> keys=tracks.keys();keys.hasNext();){String id=keys.next();JSONObject row=tracks.getJSONObject(id);if(!id.matches("[a-f0-9]{24}"))throw new Exception("统计标识无效");Json.put(cleanTracks,id,Json.obj("title",text(row.opt("title"),300),"artist",text(row.opt("artist"),300)));}int count=0;for(Iterator<String> keys=days.keys();keys.hasNext();){String date=keys.next();if(!date.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}"))throw new Exception("统计日期无效");JSONObject items=days.getJSONObject(date).getJSONObject("tracks"),clean=new JSONObject();double total=0;long plays=0;for(Iterator<String> ids=items.keys();ids.hasNext();){String id=ids.next();JSONObject item=items.getJSONObject(id);double seconds=item.getDouble("seconds"),n=item.getDouble("plays");if(++count>100000||!cleanTracks.has(id)||!Double.isFinite(seconds)||seconds<0||seconds>86400||!Double.isFinite(n)||n!=Math.floor(n)||n<0||n>10000)throw new Exception("统计条目无效");Json.put(clean,id,Json.obj("seconds",seconds,"plays",(int)n));total+=seconds;plays+=(int)n;}Json.put(cleanDays,date,Json.obj("date",date,"tracks",clean,"seconds",total,"plays",plays));}return Json.obj("startedAt",value.getDouble("startedAt"),"tracks",cleanTracks,"days",cleanDays);}
    static JSONObject payload(JSONObject raw)throws Exception{JSONObject original=raw.getJSONObject("personal"),personal=new JSONObject(),result=Json.obj("personal",personal);for(String key:List.of("liked","favorites"))if(original.has(key))Json.put(personal,key,tracks(original.getJSONArray(key)));if(original.has("history")){JSONArray rows=original.getJSONArray("history"),clean=new JSONArray();if(rows.length()>10000)throw new Exception("播放历史过大");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i),song=track(row.getJSONObject("track"));double at=row.getDouble("playedAt");if(!Double.isFinite(at)||at<0)throw new Exception("播放时间无效");clean.put(Json.obj("id",song.getString("id"),"track",song,"playedAt",at));}Json.put(personal,"history",clean);}if(original.has("playlists")){JSONArray rows=original.getJSONArray("playlists"),clean=new JSONArray();if(rows.length()>1000)throw new Exception("歌单数量过大");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);clean.put(Json.obj("name",text(row.opt("name"),100),"tracks",tracks(row.getJSONArray("tracks"))));}Json.put(personal,"playlists",clean);}if(raw.has("profile"))Json.put(result,"profile",profile(raw.getJSONObject("profile")));if(raw.has("stats"))Json.put(result,"stats",stats(raw.getJSONObject("stats")));if(raw.has("appearance")){JSONObject value=raw.getJSONObject("appearance"),clean=Json.obj("transparency",Math.max(0,Math.min(90,value.optDouble("transparency"))));if(value.has("media")){JSONObject media=value.getJSONObject("media");String kind=media.getString("kind"),base64=media.getString("base64");if(!List.of("image","video").contains(kind)||base64.length()>(kind.equals("video")?44:17)*1024*1024||!base64.matches("[A-Za-z0-9+/]*={0,2}"))throw new Exception("背景媒体无效或过大");Json.put(clean,"media",Json.obj("kind",kind,"name",text(media.opt("name"),120),"base64",base64));}Json.put(result,"appearance",clean);}if(raw.optJSONObject("extensions")!=null&&raw.getJSONObject("extensions").has("personalFeatures")){JSONObject extension=PersonalFeatureFormat.clean(raw.getJSONObject("extensions").getJSONObject("personalFeatures"));Json.put(extension,"journal",new JSONArray());Json.put(result,"extensions",Json.obj("personalFeatures",extension));}if(raw.optJSONObject("extensions")!=null&&raw.getJSONObject("extensions").has("featureSettings")){JSONObject extensions=result.optJSONObject("extensions");if(extensions==null)extensions=new JSONObject();Json.put(extensions,"featureSettings",FeatureSettingsFormat.clean(raw.getJSONObject("extensions").getJSONObject("featureSettings")));Json.put(result,"extensions",extensions);}return result;}
    static String sha(String text)throws Exception{byte[] bytes=java.security.MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8));StringBuilder result=new StringBuilder();for(byte b:bytes)result.append(String.format(Locale.ROOT,"%02x",b&255));return result.toString();}
    static String encode(JSONObject value)throws Exception{String body=payload(value).toString(),text=Json.obj("format","zenix-backup","schemaVersion",1,"createdAt",System.currentTimeMillis(),"payload",body,"sha256",sha(body)).toString();if(text.getBytes(StandardCharsets.UTF_8).length>MAX_BYTES)throw new Exception("备份超过 48 MiB，请取消背景媒体后重试");return text;}
    static JSONObject decode(String text)throws Exception{if(text.getBytes(StandardCharsets.UTF_8).length>MAX_BYTES)throw new Exception("备份超过 48 MiB");JSONObject envelope=new JSONObject(text);if(!envelope.optString("format").equals("zenix-backup"))throw new Exception("这不是 Zenix 资料备份");if(envelope.optInt("schemaVersion")>1)throw new Exception("备份来自较新版本，请先更新 Zenix");String body=envelope.optString("payload");if(envelope.optInt("schemaVersion")!=1||!sha(body).equals(envelope.optString("sha256")))throw new Exception("备份完整性校验失败");return payload(new JSONObject(body));}
    static String identity(JSONObject track){return track.optString("source").equals("local")?"local:"+key(track):track.optString("source")+":"+track.optString("providerId")+":"+track.optString("remoteId",track.optString("id"));}
    static JSONObject restoreTrack(JSONObject track,JSONArray local){if(!track.optString("source").equals("local"))return Json.copy(track);JSONObject match=null;int matches=0;if(local!=null)for(int i=0;i<local.length();i++){JSONObject item=local.optJSONObject(i);if(item!=null&&norm(item.optString("title")).equals(norm(track.optString("title")))&&norm(item.optString("artist")).equals(norm(track.optString("artist")))&&norm(item.optString("album")).equals(norm(track.optString("album")))&&item.optDouble("duration")>0&&track.optDouble("duration")>0&&Math.abs(item.optDouble("duration")-track.optDouble("duration"))<=3){matches++;match=item;}}JSONObject result=matches==1?Json.copy(match):Json.copy(track);Json.put(result,"source","local");Json.put(result,"availability",matches==1?"playable":"unavailable");return result;}
    static JSONArray add(JSONArray existing,JSONArray incoming,JSONArray local,int[] counts)throws Exception{JSONArray result=new JSONArray();Set<String> seen=new HashSet<>();for(int i=0;i<existing.length();i++){JSONObject song=existing.getJSONObject(i);if(song.optString("source").equals("local")&&song.optString("availability").equals("unavailable"))song=restoreTrack(song,local);result.put(song);seen.add(identity(song));}for(int i=0;i<incoming.length();i++){JSONObject song=restoreTrack(incoming.getJSONObject(i),local);if(seen.add(identity(song))){result.put(song);counts[0]++;if(song.optString("availability").equals("unavailable"))counts[2]++;}else counts[1]++;}return result;}
    static String signature(JSONArray values)throws Exception{StringBuilder text=new StringBuilder();for(int i=0;i<values.length();i++)text.append(identity(values.getJSONObject(i))).append('\n');return text.toString();}
    static JSONObject mergePersonal(JSONObject current,JSONObject incoming,Set<String> selected,JSONArray local)throws Exception{JSONObject next=Json.copy(current);int[] counts={0,0,0};for(String key:List.of("liked","favorites"))if(selected.contains(key)&&incoming.has(key))Json.put(next,key,add(next.getJSONArray(key),incoming.getJSONArray(key),local,counts));if(selected.contains("history")&&incoming.has("history")){Map<String,JSONObject> rows=new LinkedHashMap<>();JSONArray existing=next.getJSONArray("history"),values=incoming.getJSONArray("history");for(int i=0;i<existing.length();i++){JSONObject row=existing.getJSONObject(i);rows.put(identity(row.getJSONObject("track")),row);}for(int i=0;i<values.length();i++){JSONObject row=values.getJSONObject(i),song=restoreTrack(row.getJSONObject("track"),local);String key=identity(song);JSONObject old=rows.get(key);if(old==null)counts[0]++;else if(row.optDouble("playedAt")<=old.optDouble("playedAt"))counts[1]++;if(old==null||row.optDouble("playedAt")>old.optDouble("playedAt"))rows.put(key,Json.obj("id",old==null?song.getString("id"):old.getString("id"),"track",song,"playedAt",row.getDouble("playedAt")));}List<JSONObject> sorted=new ArrayList<>(rows.values());sorted.sort((a,b)->Double.compare(b.optDouble("playedAt"),a.optDouble("playedAt")));Json.put(next,"history",new JSONArray(sorted.subList(0,Math.min(300,sorted.size()))));}if(selected.contains("playlists")&&incoming.has("playlists")){JSONArray lists=next.getJSONArray("playlists"),values=incoming.getJSONArray("playlists");for(int i=0;i<values.length();i++){JSONObject row=values.getJSONObject(i);int addedBefore=counts[0];JSONArray songs=add(new JSONArray(),row.getJSONArray("tracks"),local,counts);String name=row.getString("name"),base=name.replaceAll("（导入(?: \\d+)?）$",""),signature=signature(songs);boolean identical=false;Set<String> names=new HashSet<>();for(int j=0;j<lists.length();j++){JSONObject old=lists.getJSONObject(j);JSONArray oldTracks=old.getJSONArray("tracks");for(int k=0;k<oldTracks.length();k++){JSONObject song=oldTracks.getJSONObject(k);if(song.optString("source").equals("local")&&song.optString("availability").equals("unavailable"))oldTracks.put(k,restoreTrack(song,local));}names.add(old.getString("name"));if(old.getString("name").replaceAll("（导入(?: \\d+)?）$","").equals(base)&&signature(old.getJSONArray("tracks")).equals(signature))identical=true;}if(identical){counts[0]=addedBefore;counts[1]++;continue;}int suffix=1;while(names.contains(name))name=row.getString("name").substring(0,Math.min(85,row.getString("name").length()))+"（导入 "+suffix+++"）";lists.put(Json.obj("id","list-"+UUID.randomUUID(),"name",name,"tracks",songs));}}return Json.obj("personal",next,"added",counts[0],"skipped",counts[1],"unavailable",counts[2]);}
    static JSONObject preview(JSONObject value)throws Exception{JSONObject personal=value.getJSONObject("personal"),counts=new JSONObject();Set<String> local=new HashSet<>();JSONArray lists=new JSONArray();for(String key:List.of("liked","favorites","history","playlists"))if(personal.has(key)){JSONArray rows=personal.getJSONArray(key);Json.put(counts,key,rows.length());for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(key.equals("playlists")){JSONArray songs=row.getJSONArray("tracks");lists.put(Json.obj("name",row.getString("name"),"count",songs.length()));for(int j=0;j<songs.length();j++){JSONObject song=songs.getJSONObject(j);if(song.optString("source").equals("local"))local.add(identity(song));}}else{JSONObject song=key.equals("history")?row.getJSONObject("track"):row;if(song.optString("source").equals("local"))local.add(identity(song));}}}for(String key:List.of("profile","appearance","stats"))if(value.has(key))Json.put(counts,key,key.equals("stats")?value.getJSONObject(key).getJSONObject("days").length():1);if(value.optJSONObject("extensions")!=null&&value.getJSONObject("extensions").has("personalFeatures"))Json.put(counts,"personalFeatures",value.getJSONObject("extensions").getJSONObject("personalFeatures").getJSONArray("bookmarks").length());if(value.optJSONObject("extensions")!=null&&value.getJSONObject("extensions").has("featureSettings"))Json.put(counts,"featureSettings",1);return Json.obj("counts",counts,"localCount",local.size(),"playlists",lists);}
    static JSONObject mergeStats(JSONObject old,JSONObject incoming)throws Exception{JSONObject next=Json.copy(old),tracks=next.getJSONObject("tracks"),days=next.getJSONObject("days"),newTracks=incoming.getJSONObject("tracks"),newDays=incoming.getJSONObject("days");Json.put(next,"startedAt",Math.min(old.getDouble("startedAt"),incoming.getDouble("startedAt")));for(Iterator<String> ids=newTracks.keys();ids.hasNext();){String id=ids.next();Json.put(tracks,id,newTracks.get(id));}for(Iterator<String> dates=newDays.keys();dates.hasNext();){String date=dates.next();JSONObject day=days.optJSONObject(date);if(day==null){day=Json.obj("date",date,"tracks",new JSONObject());Json.put(days,date,day);}JSONObject items=day.getJSONObject("tracks"),newItems=newDays.getJSONObject(date).getJSONObject("tracks");for(Iterator<String> ids=newItems.keys();ids.hasNext();){String id=ids.next();JSONObject item=newItems.getJSONObject(id),previous=items.optJSONObject(id);Json.put(items,id,Json.obj("seconds",Math.max(item.getDouble("seconds"),previous==null?0:previous.optDouble("seconds")),"plays",Math.max(item.getInt("plays"),previous==null?0:previous.optInt("plays"))));}}return stats(next);}
    static String canonical(Object value)throws Exception{if(value instanceof JSONObject){JSONObject object=(JSONObject)value;List<String> keys=new ArrayList<>();object.keys().forEachRemaining(keys::add);Collections.sort(keys);StringBuilder out=new StringBuilder("{");for(String key:keys){if(out.length()>1)out.append(',');out.append(JSONObject.quote(key)).append(':').append(canonical(object.get(key)));}return out.append('}').toString();}if(value instanceof JSONArray){JSONArray array=(JSONArray)value;StringBuilder out=new StringBuilder("[");for(int i=0;i<array.length();i++){if(i>0)out.append(',');out.append(canonical(array.get(i)));}return out.append(']').toString();}if(value instanceof Number)return JSONObject.numberToString((Number)value);return value instanceof String?JSONObject.quote((String)value):String.valueOf(value);}
}
